import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2022-09-22","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-09-22","date":"2022-09-22T00:00:00.000Z","updated":"2022-09-27T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","CRUSH 算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-09-22.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-09-22.md","lastUpdated":1780460162000}'),i={name:"posts/2022/Ceph_Performance_Meeting_2022-09-22.md"};function l(s,e,a,p,_,g){return r(),n("div",null,[...e[0]||(e[0]=[o("<p><strong>会议纪要</strong>：</p><p>本次会议主要讨论了Ceph分布式存储系统的性能优化和改进，参会者包括Mark、Ronan、Adam等。</p><p><strong>主要讨论内容</strong>：</p><ul><li><strong>Adam的工作</strong>：Adam介绍了他对Ceph对象存储的性能改进工作，包括通过单一对象跟踪器来管理所有对象的分配，从而减少共享数据块的使用，并简化数据结构。这一方法显著降低了CPU使用率和IOPS，减少了空间放大和写入负载，并提高了性能。</li><li><strong>Mark的工作</strong>：Mark讨论了他对对象进行碎片整理的工作，以减少写入操作的数量，并实现了一个单一跟踪器来跟踪所有对象及其克隆。这种方法也有助于降低CPU使用率，但需要进一步优化以减少磁盘影响。</li><li><strong>性能改进方法</strong>：会议还讨论了通过将负载从共享块转移到CPU密集型操作来改善性能的方法，以及如何通过引入Jitter来平滑IO负载。</li><li><strong>RGW的HTTP 3前端</strong>：Ronan提到了rgw的HTTP 3前端开发的进展，这可能会带来性能提升。</li><li><strong>CPU使用情况</strong>：会议最后讨论了当前Ceph集群部署的CPU使用情况，并探讨了如何进一步降低开销。</li></ul><p><strong>行动计划</strong>：</p><ul><li>继续测试和优化Adam提出的方法。</li><li>探讨将新方法集成到现有系统的可能性。</li><li>分析新方法在硬盘驱动器上的性能表现。</li><li>关注rgw的HTTP 3前端开发的进展，并评估其对性能的影响。</li><li>计划下周继续讨论，并鼓励大家关注Ceph的性能优化和改进工作。</li></ul><p><strong>改进点</strong>：</p><ul><li>确保了会议纪要准确反映了原始内容的要点，包括关键细节、主要议题、决定的事项以及后续的行动计划。</li><li>保留了所有重要的Ceph相关领域的英文原文关键词。</li><li>对会议内容进行了更详细的总结，包括每个主题的详细信息。</li></ul>",8)])])}const C=t(i,[["render",l]]);export{c as __pageData,C as default};
